int bawang_font_overlay_apply(uint8_t *rom, size_t rom_size, int simplified)
{
    if (!rom) return 0;
    /* Validate ALL 355 source slots before writing any byte. A bad version
     * of the ROM cannot leave the buffer half-patched. Allow original or
     * simplified data so changing language remains lossless and reversible. */
    for (size_t i = 0; i < sizeof(entries)/sizeof(entries[0]); ++i) {
        const FontEntry *e = &entries[i];
        if (e->offset > rom_size || rom_size - e->offset < 32) return 0;
        const uint8_t *at = rom + e->offset;
        if (memcmp(at, e->original, 32) != 0 &&
            memcmp(at, e->simplified, 32) != 0) return 0;
    }
    for (size_t i = 0; i < sizeof(entries)/sizeof(entries[0]); ++i) {
        const FontEntry *e = &entries[i];
        memcpy(rom + e->offset, simplified ? e->simplified : e->original, 32);
    }
    return 1;
}
